import { mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { inflateRawSync } from 'node:zlib';

// Actions/upload-artifact produces the *downloadable* ZIP itself. Uploading
// the installable ZIP would create ZIP-inside-ZIP; instead, stage its exact
// verified contents under one versioned directory. Tag releases still attach
// the installable ZIP generated by pack.mjs without changes.
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const { version } = JSON.parse(readFileSync(path.join(root, 'package.json'), 'utf8'));
const folder = `Cocos-Gizmos-v${version}`;
const zip = readFileSync(path.join(root, 'release', folder + '.zip'));
const stagingRoot = path.join(root, 'release', 'dev-artifact');
const stageDir = path.join(stagingRoot, folder);
rmSync(stagingRoot, { recursive: true, force: true });
mkdirSync(stageDir, { recursive: true });

let offset = 0;
let count = 0;
const seen = new Set();
while (offset + 30 <= zip.length && zip.readUInt32LE(offset) === 0x04034b50) {
    const flags = zip.readUInt16LE(offset + 6);
    const compression = zip.readUInt16LE(offset + 8);
    const compressedSize = zip.readUInt32LE(offset + 18);
    const uncompressedSize = zip.readUInt32LE(offset + 22);
    const filenameSize = zip.readUInt16LE(offset + 26);
    const extraSize = zip.readUInt16LE(offset + 28);
    const name = zip.subarray(offset + 30, offset + 30 + filenameSize).toString('utf8');
    const dataStart = offset + 30 + filenameSize + extraSize;
    const dataEnd = dataStart + compressedSize;
    if (dataEnd > zip.length || !filenameSize || (flags & 8) ||
        (compression !== 0 && compression !== 8))
        throw new Error('[dev-artifact] Unsupported or malformed ZIP entry: ' + name);
    if (name !== folder + '/' && (!name.startsWith(folder + '/') ||
        name.endsWith('/') || name.slice(folder.length + 1).includes('..') ||
        name.includes('\\') || path.posix.normalize(name) !== name))
        throw new Error('[dev-artifact] Unsafe or incorrectly rooted file: ' + name);
    if (seen.has(name)) throw new Error('[dev-artifact] Duplicate ZIP entry: ' + name);
    seen.add(name);
    const file = name.slice(folder.length + 1);
    if (file) {
        if (file.toLowerCase().endsWith('.zip'))
            throw new Error('[dev-artifact] Nested ZIP forbidden: ' + file);
        const bytes = zip.subarray(dataStart, dataEnd);
        const data = compression === 8 ? inflateRawSync(bytes) : bytes;
        if (data.length !== uncompressedSize)
            throw new Error('[dev-artifact] ZIP file size mismatch: ' + name);
        const destination = path.join(stageDir, file);
        mkdirSync(path.dirname(destination), { recursive: true });
        writeFileSync(destination, data);
        count++;
    }
    offset = dataEnd;
}
if (offset === 0 || !seen.has(folder + '/') || !seen.has(folder + '/package.json') ||
    count < 10 || readdirSync(stagingRoot).join(',') !== folder)
    throw new Error('[dev-artifact] Expected exactly one versioned extension folder');
const manifest = JSON.parse(readFileSync(path.join(stageDir, 'package.json'), 'utf8'));
if (manifest.name !== 'cocos-gizmos' || manifest.version !== version)
    throw new Error('[dev-artifact] Extracted extension manifest mismatch');
console.log(`[dev-artifact] staged ${count} files: ${folder}/ (no nested ZIP)`);
